import itertools

assistants = ['F','G','H','I','M','P']
departments = [0,1,2]

# generate all possible department assignments: each department is a frozenset of 3 assistants
all_dept_assignments = list(itertools.combinations(assistants, 3))
print("Total department assignments per dept:", len(all_dept_assignments))

# generate all possible triples of departments (with repetition allowed)
all_possible = []
for d1 in all_dept_assignments:
    for d2 in all_dept_assignments:
        for d3 in all_dept_assignments:
            # each assistant must be in at least one department
            # compute how many departments each assistant is in
            counts = {a: 0 for a in assistants}
            for dept in (d1, d2, d3):
                for a in dept:
                    counts[a] += 1
            if all(c >= 1 for c in counts.values()):
                # condition (1): exactly one assistant in all three departments
                triple_assistants = [a for a, c in counts.items() if c == 3]
                if len(triple_assistants) != 1:
                    continue
                # condition (2): F and G not in same department
                if any('F' in dept and 'G' in dept for dept in (d1, d2, d3)):
                    continue
                # condition (3): H and I not in same department
                if any('H' in dept and 'I' in dept for dept in (d1, d2, d3)):
                    continue
                # additional: F and M not in same department
                if any('F' in dept and 'M' in dept for dept in (d1, d2, d3)):
                    continue
                all_possible.append((d1, d2, d3, counts))

print("Number of valid assignments:", len(all_possible))
if len(all_possible) == 0:
    print("No valid assignments")
else:
    # check each option
    # A: F and H are in charge of the same department (i.e., there exists at least one department containing both F and H)
    # Actually "are in charge of the same department" means they share at least one department? The phrasing "are in charge of the same department" could mean they are both assigned to that department (i.e., they share a department). Yes.
    # We need "must be true" meaning for every valid assignment, the statement holds.
    # Let's evaluate each option.
    option_a_true = all(any('F' in dept and 'H' in dept for dept in (d1,d2,d3)) for d1,d2,d3,_ in all_possible)
    option_b_true = all(any('F' in dept and 'I' in dept for dept in (d1,d2,d3)) for d1,d2,d3,_ in all_possible)
    option_c_true = all(any('I' in dept and 'P' in dept for dept in (d1,d2,d3)) for d1,d2,d3,_ in all_possible)
    option_d_true = all(any('M' in dept and 'G' in dept for dept in (d1,d2,d3)) for d1,d2,d3,_ in all_possible)

    print("Option A (F and H share a department) must be true?", option_a_true)
    print("Option B (F and I share a department) must be true?", option_b_true)
    print("Option C (I and P share a department) must be true?", option_c_true)
    print("Option D (M and G share a department) must be true?", option_d_true)

    # also output which ones are always true
    if option_a_true:
        print("A is always true")
    if option_b_true:
        print("B is always true")
    if option_c_true:
        print("C is always true")
    if option_d_true:
        print("D is always true")

    # Let's also compute distribution of counts for each assistant across all valid assignments
    # to see patterns
    from collections import Counter
    count_dist = {a: Counter() for a in assistants}
    for d1,d2,d3,counts in all_possible:
        for a in assistants:
            count_dist[a][counts[a]] += 1
    print("\nCount distributions:")
    for a in assistants:
        print(f"{a}: {sorted(count_dist[a].items())}")
